<?php
require __DIR__.'/includes/bootstrap.php';$user=require_user(true);require __DIR__.'/includes/modules.php';require __DIR__.'/includes/layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{transaction(function(){
 $action=text_value($_POST,'action',20,true);
 if($action==='settings'){$name=text_value($_POST,'business_name',160,true);$notifications=enum_value($_POST['notifications_enabled']??'',['on','off']);query('UPDATE system_settings SET setting_value=? WHERE setting_key=?',[$name,'business_name']);query('UPDATE system_settings SET setting_value=? WHERE setting_key=?',[$notifications==='on'?'1':'0','notifications_enabled']);audit('settings_updated','settings');}
 elseif($action==='retry'){query('UPDATE notification_queue SET attempts=0,available_at=UTC_TIMESTAMP() WHERE sent_at IS NULL');audit('notification_retries_requested','settings');}
 else throw new ValidationError('Invalid action.');
});$_SESSION['flash']='Settings saved.';redirect('admin/settings.php');}catch(ValidationError $ex){$error=$ex->getMessage();}}
$settings=query('SELECT setting_key,setting_value FROM system_settings')->fetchAll(PDO::FETCH_KEY_PAIR);$pending=(int)query('SELECT COUNT(*) FROM notification_queue WHERE sent_at IS NULL')->fetchColumn();$failed=(int)query('SELECT COUNT(*) FROM notification_queue WHERE sent_at IS NULL AND attempts>=5')->fetchColumn();
page_header('System settings',$user);if($error)echo '<p class="notice error">'.e($error).'</p>';echo '<form class="panel" method="post">'.csrf_input().'<input type="hidden" name="action" value="settings">';input_field('business_name','Internal business name',$settings['business_name'],'text',true);select_field('notifications_enabled','Administrative notifications',['on'=>'Enabled','off'=>'Paused'],$settings['notifications_enabled']==='1'?'on':'off');echo '<button>Save settings</button></form><section class="panel"><h2>Notification delivery</h2><p>Mail transport: '.(config('mail_enabled')?'Enabled in private server configuration':'Disabled in private server configuration').'. Recipient: '.e(config('recipient')).'.</p><p>'.$pending.' queued · '.$failed.' reached the retry limit.</p><p>Public records are saved even when email is unavailable. A scheduled private CLI worker processes notifications. Check actual inbox delivery on the live host.</p><form method="post">'.csrf_input().'<input type="hidden" name="action" value="retry"><button>Allow queued notifications to retry</button></form></section><section class="panel"><h2>Privacy and retention</h2><p>Normal operations archive records rather than permanently delete them. Agree retention periods with the business and follow the documented restricted deletion process for valid privacy requests. Credentials and private paths are never displayed in this portal.</p></section>';page_footer();
